package org.aegis.android;

import android.content.Context;
import com.google.gson.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.Clock;
import java.util.*;
import java.util.function.BooleanSupplier;
import org.securemail.client.community.CommunityJson;
import org.securemail.client.crypto.*;
import org.securemail.client.crypto.Identity;
import org.securemail.protocol.*;
import org.securemail.ecosystem.protocol.IdentityProtocol;

/** Mail UID owns legacy identity; Core receives neither the key nor a signing primitive. */
final class MailSession implements AutoCloseable {
    static final int MAX_PACKET=192*1024,MAX_MAIL=32;
    private final PrivateVault vault;private final BooleanSupplier authorized;private volatile MailRelay relay;private final java.util.concurrent.atomic.AtomicLong revision=new java.util.concurrent.atomic.AtomicLong();private final AutomaticEncryption encryption=new AutomaticEncryption(Clock.systemUTC());
    MailSession(Context c,BooleanSupplier guard){if(!AndroidPolicy.MAIL.equals(c.getPackageName()))throw new SecurityException("Identity доступна только Почте");vault=new PrivateVault(c);authorized=guard;}
    private void guard(){if(!authorized.getAsBoolean())throw new SecurityException("Нужен действующий допуск Почты");}
    private void guard(long start){guard();if(revision.get()!=start)throw new SecurityException("Операция отменена блокировкой сессии");}
    void importBackup(InputStream input,char[] password,String account)throws Exception {
        long start=revision.get();guard(start);try(MailBackup backup=MailBackup.read(input,password,account)){guard(start);byte[] old=vault.get("mail-account");if(old!=null){Arrays.fill(old,(byte)0);throw new SecurityException("Identity уже импортирована; автоматическая замена запрещена");}byte[] secret=backup.identity.privateKey();byte[] record=null;try{record=Binary.encode(out->{Binary.bytes(out,backup.identity.publicKey());Binary.bytes(out,secret);Binary.text(out,backup.nickname);out.writeInt(backup.contacts.size());for(UserInfo peer:backup.contacts)peer.write(out);});guard(start);vault.put("mail-account",record);}finally{Arrays.fill(secret,(byte)0);if(record!=null)Arrays.fill(record,(byte)0);}}
    }
    private static final class Account {final Identity identity;final String nickname;final List<UserInfo> contacts;Account(Identity i,String n,List<UserInfo> c){identity=i;nickname=n;contacts=c;}}
    private Account account(String expected)throws Exception {
        guard();byte[] bytes=vault.get("mail-account"),secret=null;if(bytes==null)throw new SecurityException("Импортируйте защищённую резервную копию identity из Почты");try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(bytes))){byte[] pub=Binary.bytes(in,44);secret=Binary.bytes(in,128);Identity identity=Identity.restore(pub,secret);if(!identity.userId().equals(expected))throw new SecurityException("Локальная identity другого аккаунта");String nickname=Binary.text(in,32);Limits.nickname(nickname);int n=in.readInt();if(n<0||n>32)throw new IOException("Повреждённые контакты");List<UserInfo> contacts=new ArrayList<>();for(int i=0;i<n;i++)contacts.add(UserInfo.read(in));Binary.end(in);return new Account(identity,nickname,contacts);}finally{Arrays.fill(bytes,(byte)0);if(secret!=null)Arrays.fill(secret,(byte)0);}
    }
    byte[] approveVoice(String pending,IdentityProtocol.Capability own,byte[] server)throws Exception {
        long start=revision.get();guard(start);String[] parts=pending.split("\n",-1);if(parts.length!=2||parts[0].length()!=43)throw new SecurityException("Неверный запрос Гласа");IdentityProtocol.nonceValue(parts[0]);long now=System.currentTimeMillis();IdentityProtocol.Capability glas=VoiceHandoff.voiceCapability(parts[1],own,server,now);if(own.appId!=IdentityProtocol.App.MAIL||!own.capabilities.containsAll(EnumSet.of(IdentityProtocol.Scope.MAIL_READ,IdentityProtocol.Scope.MAIL_SEND,IdentityProtocol.Scope.CONTACTS_READ)))throw new SecurityException("Нужен допуск Почты");Account account=account(own.accountId);
        long until=Math.min(glas.expiresAt,glas.offlineUntil);if(until<=now)throw new SecurityException("Допуск истёк");var unsigned=new org.securemail.glas.protocol600.GlasProtocol600.Delegation(glas.audience,account.identity.publicKey(),glas.deviceId,glas.generation,glas.proofKey,now,until,parts[0],new byte[64]);var delegation=unsigned.signed(account.identity.sign(unsigned.signingBytes()));List<org.securemail.client.voice600.GlasGrant600.Contact> contacts=new ArrayList<>();for(UserInfo peer:account.contacts)contacts.add(new org.securemail.client.voice600.GlasGrant600.Contact(peer,false));var draft=new org.securemail.client.voice600.GlasGrant600(delegation,contacts,new byte[64]);byte[] encoded=draft.signed(account.identity.sign(draft.signingBytes())).encode();guard(start);VoiceHandoff.validateGrant(encoded,glas,server,parts[0],now);return encoded;
    }
    String publicIdentity(String expected)throws Exception {Account a=account(expected);return a.nickname+"\n"+Identity.fingerprint(a.identity.publicKey())+"\nИмпортировано контактов: "+a.contacts.size();}
    void configure(String onion,int port,String relayKey)throws Exception {guard();Limits.onion(onion);if(port<1||port>65535)throw new IllegalArgumentException("Порт Relay");JsonObject j=new JsonObject();j.addProperty("onion",onion);j.addProperty("port",port);byte[] service=IdentityProtocol.unb64(relayKey,44);IdentityProtocol.publicKey(service);j.addProperty("relayKey",IdentityProtocol.b64(service));vault.put("mail-relay-config",j.toString().getBytes(StandardCharsets.UTF_8));close();}
    void login(String expected,int socks,char[] password,IdentityProtocol.Capability capability)throws Exception {login(expected,socks,password,capability,false);}
    void login(String expected,int socks,char[] password,IdentityProtocol.Capability capability,boolean register)throws Exception {Account a=account(expected);byte[] bytes=vault.get("mail-relay-config");if(bytes==null)throw new SecurityException("Укажите публичный onion Relay");JsonObject j;try{j=CommunityJson.parse(bytes);}finally{Arrays.fill(bytes,(byte)0);}close();MailRelay next=new MailRelay(j.get("onion").getAsString(),j.get("port").getAsInt(),socks,authorized);relay=next;try{if(register)next.register(a.identity,a.nickname,password,capability,IdentityProtocol.unb64(j.get("relayKey").getAsString(),44),vault::prove);next.login(a.identity,a.nickname,password,capability,IdentityProtocol.unb64(j.get("relayKey").getAsString(),44),vault::prove);}catch(Exception failure){next.close();throw failure;}}
    private MailRelay online(){guard();MailRelay r=relay;if(r==null||!r.loggedIn())throw new SecurityException("Войдите в Relay");return r;}
    List<String> contacts(String expected)throws Exception {return account(expected).contacts.stream().map(UserInfo::nickname).collect(java.util.stream.Collectors.toList());}
    String send(String expected,String nickname,String text)throws Exception {long start=revision.get();Account a=account(expected);String nick=Limits.nickname(nickname);UserInfo peer=a.contacts.stream().filter(p->p.nickname().equals(nick)).findFirst().orElseThrow(()->new SecurityException("Получатель должен быть проверенным контактом из резервной копии"));try(PlainMessage message=PlainMessage.text(text)){guard();EncryptedPacket p=encryption.encrypt(message,86400,86400_000L,a.identity,a.nickname,peer);if(PacketCodec.encode(p).length>MAX_PACKET)throw new IOException("Пакет превышает текущий лимит Android");guard(start);online().send(p,a.identity,peer);guard(start);return p.messageId();}}
    private static final class Entry {final String id,digest;final long received,expires,deadline;Entry(String id,String digest,long received,long expires,long deadline){this.id=Limits.messageId(id);this.digest=Limits.userId(digest);if(received<1||expires<=received||deadline<1)throw new IllegalArgumentException("Срок записи");this.received=received;this.expires=expires;this.deadline=deadline;}}
    private List<Entry> index()throws Exception {byte[] bytes=vault.get("mail-inbox-index");if(bytes==null)return new ArrayList<>();try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(bytes))){int count=in.readInt();if(count<0||count>4096)throw new IOException("Повреждённый индекс");List<Entry> entries=new ArrayList<>();Set<String> ids=new HashSet<>();for(int i=0;i<count;i++){Entry e=new Entry(Binary.text(in,36),Binary.text(in,64),in.readLong(),in.readLong(),in.readLong());if(!ids.add(e.id))throw new IOException("Дублированный индекс");entries.add(e);}Binary.end(in);return entries;}finally{Arrays.fill(bytes,(byte)0);}}
    private void saveIndex(List<Entry> entries)throws Exception {byte[] bytes=Binary.encode(out->{out.writeInt(entries.size());for(Entry e:entries){Binary.text(out,e.id);Binary.text(out,e.digest);out.writeLong(e.received);out.writeLong(e.expires);out.writeLong(e.deadline);}});try{guard();vault.put("mail-inbox-index",bytes);}finally{Arrays.fill(bytes,(byte)0);}}
    private long clock()throws Exception {long now=System.currentTimeMillis();byte[] saved=vault.get("mail-clock");try{if(saved!=null){if(saved.length!=8)throw new IOException("Повреждённые часы Почты");now=Math.max(now,new DataInputStream(new ByteArrayInputStream(saved)).readLong());}}finally{if(saved!=null)Arrays.fill(saved,(byte)0);}final long value=now;vault.put("mail-clock",Binary.encode(out->out.writeLong(value)));return now;}
    int fetch(String expected)throws Exception {
        long start=revision.get();Account a=account(expected);int fetched=0;for(int n=0;n<8;n++){guard(start);EncryptedPacket p=online().fetch();if(p==null)break;long now=clock();if(!p.recipientId().equals(a.identity.userId())||!Identity.verifyPacket(p)||p.createdAt()>now+300000||p.deliveryDeadline()<=now)throw new SecurityException("Некорректный входящий пакет");List<Entry> entries=index();String digest=Identity.id(Identity.digest(p));Entry existing=entries.stream().filter(e->e.id.equals(p.messageId())).findFirst().orElse(null);long received;
            if(existing!=null){if(!existing.digest.equals(digest))throw new SecurityException("Конфликт идентификатора письма");received=existing.received;}
            else {for(Entry e:entries)if(e.expires<=now)vault.remove("mail-"+e.id);entries.removeIf(e->e.deadline<=now);if(entries.size()>=1024||entries.stream().filter(e->e.expires>now).count()>=MAX_MAIL)throw new IOException("Локальный ящик заполнен; удалите истёкшие письма или откройте настольную Почту");byte[] packet=PacketCodec.encode(p);try{vault.put("mail-"+p.messageId(),packet);}finally{Arrays.fill(packet,(byte)0);}Entry entry=new Entry(p.messageId(),digest,now,Math.addExact(now,p.ttlAfterDelivery()*1000L),p.deliveryDeadline());entries.add(entry);saveIndex(entries);received=now;fetched++;}
            guard(start);online().acknowledge(a.identity.receipt(p,received));
        }return fetched;
    }
    List<String> inbox(String expected)throws Exception {account(expected);long now=clock();List<String> result=new ArrayList<>();for(Entry entry:index())if(entry.expires>now){byte[] packet=vault.get("mail-"+entry.id);if(packet==null)continue;try{EncryptedPacket p=PacketCodec.decode(packet,MAX_PACKET);if(!p.messageId().equals(entry.id)||!entry.digest.equals(Identity.id(Identity.digest(p)))||!Identity.verifyPacket(p))throw new SecurityException("Письмо повреждено");result.add(entry.id+" · "+p.senderNickname());}finally{Arrays.fill(packet,(byte)0);}}return result;}
    String read(String expected,String id)throws Exception {long start=revision.get();Account a=account(expected);Limits.messageId(id);long now=clock();Entry e=index().stream().filter(v->v.id.equals(id)).findFirst().orElseThrow(()->new IOException("Письмо недоступно"));if(e.expires<=now){vault.remove("mail-"+id);throw new IOException("Срок хранения письма истёк");}byte[] bytes=vault.get("mail-"+id);if(bytes==null)throw new IOException("Письмо недоступно");try{EncryptedPacket p=PacketCodec.decode(bytes,MAX_PACKET);if(!e.digest.equals(Identity.id(Identity.digest(p)))||!p.messageId().equals(id))throw new SecurityException("Письмо повреждено");if(!AutomaticEncryption.supports(p))throw new IOException("Этот старый защищённый формат пока открывается только настольной Почтой");try(PlainMessage message=encryption.decrypt(p,a.identity,128*1024)){guard(start);if(message.protectedLetter())throw new IOException("Защищённое letter-password/FF1 письмо сохранено; его редактор Android ещё недоступен");String warning=a.contacts.stream().anyMatch(u->u.userId().equals(p.senderId())&&MessageDigest.isEqual(u.publicKey(),p.senderPublicKey()))?"Проверенный контакт":"Подпись корректна; отправитель ещё не является проверенным контактом";return warning+"\nОт: "+p.senderNickname()+"\n"+(message.subject().isEmpty()?"":message.subject()+"\n\n")+message.text()+(message.streamingAttachments()?"\n\nЕсть потоковые вложения. Их загрузка и экспорт в Android пока недоступны":"\n\nВложений: "+message.files().size()+" (экспорт Android ещё недоступен)");}}finally{Arrays.fill(bytes,(byte)0);}}
    @Override public void close(){revision.incrementAndGet();MailRelay r=relay;relay=null;if(r!=null)r.close();}
}
